const fs = require('fs');

function solve() {
    const data = fs.readFileSync(0, 'utf-8').trim().split(/\s+/);
    if (data.length === 0) return;
    let idx = 0;
    const n = parseInt(data[idx++]);
    const k = parseInt(data[idx++]);
    const query = [];
    for (let i = 0; i < n; i++) {
        query.push(parseInt(data[idx++]));
    }

    let cost = 0;
    const availableBooks = new Set();
    const access = new Array(81).fill(0);
    let removable = -1;

    for (let i = 0; i < n; i++) {
        access[query[i]]++;
    }

    for (let i = 0; i < n; i++) {
        const currentBook = query[i];
        const doesNotContain = !availableBooks.has(currentBook);
        if (doesNotContain) {
            cost++;
        }

        if (removable !== -1) {
            availableBooks.delete(removable);
            removable = -1;
        } else if (availableBooks.size === k && doesNotContain) {
            let removableBook = -1;
            let count = k;
            const known = new Set();
            for (let j = i + 1; j < n && count > 0; j++) {
                const qj = query[j];
                if (availableBooks.has(qj) && !known.has(qj)) {
                    count--;
                    known.add(qj);
                    removableBook = qj;
                }
            }
            if (removableBook !== -1) {
                availableBooks.delete(removableBook);
            } else {
                availableBooks.delete(availableBooks.values().next().value);
            }
        }

        availableBooks.add(currentBook);
        if (--access[currentBook] === 0) {
            removable = currentBook;
        }
    }

    console.log(cost);
}

solve();

